def transform(grid):
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]

    color_by_inner_size = {3: 8, 5: 4, 7: 3}

    for top in range(h):
        for bottom in range(top + 4, h):
            inner_h = bottom - top - 1
            color = color_by_inner_size.get(inner_h)
            if color is None:
                continue

            for left in range(w):
                for right in range(left + 4, w):
                    inner_w = right - left - 1
                    if inner_w != inner_h:
                        continue

                    # All four sides must form a 2-colored rectangular frame.
                    if not (
                        all(original[top][c] == 2 for c in range(left, right + 1))
                        and all(original[bottom][c] == 2 for c in range(left, right + 1))
                        and all(original[r][left] == 2 for r in range(top, bottom + 1))
                        and all(original[r][right] == 2 for r in range(top, bottom + 1))
                    ):
                        continue

                    interior_twos = [
                        (r, c)
                        for r in range(top + 1, bottom)
                        for c in range(left + 1, right)
                        if original[r][c] == 2
                    ]
                    if len(interior_twos) != 1:
                        continue

                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            if original[r][c] == 0:
                                out[r][c] = color

    return out
